int main(int argc,char** argv){try{
    std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_cloth_draw_tests [--adapter substring]");
    auto asset=c::loadClothLibrary("build/cloth-draw/fixtures/library.json","assets").cloths.at("solver_patch");Rig rig(adapter);Targets targets(rig);oriented(rig,targets,asset);depth(rig,targets,asset);deformation(rig,targets,asset);lifecycle(rig,targets,asset);previewClock(rig);auto errors=rig.debugErrors();require(errors==0,"Cloth rendering D3D12 debug errors");
    std::cout<<nlohmann::json{{"schema","nativegpu.cloth-draw-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"parsedPixelComponents",pixelComparisons},{"actualDrawVertices",drawnVertices},{"actualPSInvocations",shadedPixels},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"cpuVertexUpload",false},{"runtimeReadback",false},{"validationReadback","test-only pixels and pipeline queries"}}.dump()<<'\n';
}catch(const std::exception& e){std::cerr<<"GPU cloth draw failed after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
